package com.bibliotech.rental.entity;import jakarta.persistence.*;import java.time.*;@Entity public class Rental{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;private Long userId;private Long bookId;private LocalDate borrowDate,dueDate,returnDate;@Enumerated(EnumType.STRING)private Status status;public Long getId(){return id;}public Long getUserId(){return userId;}public void setUserId(Long v){userId=v;}public Long getBookId(){return bookId;}public void setBookId(Long v){bookId=v;}public LocalDate getBorrowDate(){return borrowDate;}public void setBorrowDate(LocalDate v){borrowDate=v;}public LocalDate getDueDate(){return dueDate;}public void setDueDate(LocalDate v){dueDate=v;}public LocalDate getReturnDate(){return returnDate;}public void setReturnDate(LocalDate v){returnDate=v;}public Status getStatus(){return status;}public void setStatus(Status v){status=v;}}
